def converti_ruoli(apps, schema_editor):
    """Da 4 ruoli a 3 livelli: responsabile -> admin, commerciale -> tecnico."""
    Utente = apps.get_model("core", "Utente")
    Utente.objects.filter(ruolo="responsabile").update(ruolo="admin")
    Utente.objects.filter(ruolo="commerciale").update(ruolo="tecnico")
    Utente.objects.filter(is_superuser=True).update(ruolo="admin", is_staff=True)
    Utente.objects.filter(ruolo="cliente").update(is_staff=False, is_superuser=False)
    Utente.objects.exclude(ruolo="cliente").update(is_staff=True)
    # da qui i permessi arrivano solo dal livello (gruppi): via quelli assegnati a mano
    for u in Utente.objects.filter(is_superuser=False):
        u.user_permissions.clear()


